/// Serializes writers against readers within a dataset: a batch (or a single
/// PUT) holds the write lock while committing, so concurrent GET/list
/// requests observe only the pre-batch or post-batch dataset, never a
/// partially written one.
#[derive(Default)]
struct DatasetLock {
    /// Tokio Mutex (not std): while it is held the future only awaits fs I/O.
    write: tokio::sync::Mutex<()>,
    /// Readers grab a read permit; the writer waits for outstanding readers to
    /// drain before mutating files.
    readers: tokio::sync::RwLock<()>,
}

#[derive(Clone)]
struct AppState {
    data_dir: Arc<PathBuf>,
    /// Per-dataset reader/writer exclusion, created on demand.
    locks: Arc<tokio::sync::Mutex<HashMap<String, Arc<DatasetLock>>>>,
}

impl AppState {
    async fn dataset_lock(&self, name: &str) -> Arc<DatasetLock> {
        let mut guards = self.locks.lock().await;
        guards
            .entry(name.to_owned())
            .or_insert_with(|| Arc::new(DatasetLock::default()))
            .clone()
    }
}

static TXN_COUNTER: AtomicU64 = AtomicU64::new(0);

