    key: String,
    body: Vec<u8>,
    old: Option<(Vec<u8>, SystemTime)>,
}

/// Write a whole batch through a crash-safe transaction:
///
/// 1. Stage every new file (fsynced) and a backup of every pre-existing
///    record in a private `.txn-*` directory, then fsync a `COMMITTED`
///    marker. Nothing in the dataset directory has changed yet.
/// 2. Rename each staged file over its target. After the first rename the
///    batch is committed: the fsynced marker survives a crash, and startup
///    recovery redoes any rename that did not land.
/// 3. Fsync the dataset directory so the renames are durable, then remove
///    the staging directory.
///
/// Any failure before the first rename aborts with the dataset untouched.
/// A failure after renames began rolls the already-installed records back
/// to their exact prior bytes and mtime.
async fn persist_batch(
    state: &AppState,
    name: &str,
    entries: &[(String, Value)],
) -> Result<Vec<(String, SystemTime)>, Response> {
    let internal = || error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal");
    let dir = state.data_dir.join(name);
    if let Err(e) = tokio::fs::create_dir_all(&dir).await {
        tracing_error(&e);
        return Err(internal());
    }

    let txn_id = TXN_COUNTER.fetch_add(1, Ordering::Relaxed);
    let staging = dir.join(format!(".txn-{}-{}", std::process::id(), txn_id));
    let staged_dir = staging.join("new");
    let backup_dir = staging.join("old");
    let committed = staging.join("COMMITTED");
    // Best-effort cleanup runs on every exit path; a staging dir left behind
    // by a crash is reconciled by `recover_dataset` at next startup.
    let cleanup = Cleanup(staging.clone());

    if let Err(e) = tokio::fs::create_dir_all(&staged_dir).await {
        tracing_error(&e);
        cleanup.0.rm_rf().await;
        return Err(internal());
    }
    if let Err(e) = tokio::fs::create_dir_all(&backup_dir).await {
        tracing_error(&e);
        cleanup.0.rm_rf().await;
        return Err(internal());
    }

    // Stage all writes and capture pre-state first; no target is touched yet.
    let mut staged: Vec<StagedRecord> = Vec::with_capacity(entries.len());
    for (key, value) in entries {
        let body = serde_json::to_vec(value).map_err(|e| {
            eprintln!("encode record {name}/{key}: {e}");
            internal()
        })?;
        let target = record_path(state, name, key);
        let old = match tokio::fs::read(&target).await {
            Ok(bytes) => {
                let meta = tokio::fs::metadata(&target).await.map_err(|e| {
                    tracing_error(&e);
                    internal()
                })?;
                let modified = meta.modified().map_err(|e| {
                    tracing_error(&e);
                    internal()
                })?;
                // Keep a backup so a post-commit failure can restore bytes
                // and mtime exactly.
                tokio::fs::write(backup_dir.join(format!("{key}.json")), &bytes)
                    .await
                    .map_err(|e| {
                        tracing_error(&e);
                        internal()
                    })?;
                Some((bytes, modified))
            }
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => None,
            Err(e) => {
                tracing_error(&e);
                return Err(internal());
            }
        };
        let staged_path = staged_dir.join(format!("{key}.json"));
        if let Err(e) = write_fsynced(&staged_path, &body).await {
            tracing_error(&e);
            cleanup.0.rm_rf().await;
            return Err(internal());
        }
        staged.push(StagedRecord {
            key: key.clone(),
            body,
            old,
        });
    }

    // Fsync the backup directory so staged backups and old files are durable,
    // then persist the commit marker: this is the single commit point.
    if let Err(e) = fsync_dir(&backup_dir).await {
        tracing_error(&e);
        cleanup.0.rm_rf().await;
        return Err(internal());
    }
    if let Err(e) = write_fsynced(&committed, b"committed\n").await {
        tracing_error(&e);
        cleanup.0.rm_rf().await;
        return Err(internal());
    }
    if let Err(e) = fsync_dir(&staging).await {
        tracing_error(&e);
        cleanup.0.rm_rf().await;
        return Err(internal());
    }

    // Install. Each record's completion time is taken just before its rename,
    // so mtime ordering follows install order within the batch.
    let mut applied: Vec<(String, SystemTime)> = Vec::new();
    let mut installed = 0usize;
    for rec in &staged {
        let target = record_path(state, name, rec.key.as_str());
        let when = SystemTime::now();
        if let Err(e) = tokio::fs::rename(staged_dir.join(format!("{}.json", rec.key)), &target).await
        {
