/// Restore records already replaced by a failed commit to their pre-batch
/// bytes and mtime. Records that did not pre-exist are removed.
async fn rollback_batch(
    state: &AppState,
    name: &str,
    installed: &[StagedRecord],
    backup_dir: &Path,
) {
    for rec in installed {
        let target = record_path(state, name, rec.key.as_str());
        match &rec.old {
            Some((bytes, mtime)) => {
                let tmp = backup_dir.join(format!(".restore-{}.json", rec.key));
                if write_fsynced(&tmp, bytes).await.is_ok() {
                    if tokio::fs::rename(&tmp, &target).await.is_ok() {
                        let _ = set_mtime(&target, *mtime).await;
                    } else {
                        let _ = tokio::fs::remove_file(&tmp).await;
                    }
                }
            }
            None => {
                let _ = tokio::fs::remove_file(&target).await;
            }
        }
    }
    let dir = state.data_dir.join(name);
    let _ = fsync_dir(&dir).await;
}

/// Write a file via a freshly created handle and fsync its contents.
async fn write_fsynced(path: &Path, body: &[u8]) -> std::io::Result<()> {
    let mut file = tokio::fs::File::create(path).await?;
    tokio::io::AsyncWriteExt::write_all(&mut file, body).await?;
    file.sync_all().await?;
    Ok(())
}

/// fsync a directory so that file creations and renames inside it survive a
/// crash or power loss.
async fn fsync_dir(path: &Path) -> std::io::Result<()> {
    let file = tokio::fs::File::open(path).await?;
    file.sync_all().await
}

async fn set_mtime(path: &Path, when: SystemTime) -> std::io::Result<()> {
    let file = tokio::fs::File::open(path).await?;
    file.set_modified(when).await
}

struct Cleanup(PathBuf);

impl Cleanup {
    async fn rm_rf(&self) {
        let _ = tokio::fs::remove_dir_all(&self.0).await;
    }
}

impl Drop for Cleanup {
    fn drop(&mut self) {
        // Defense in depth if an exit path forgot to await cleanup.
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

/// Reconcile any staging directories left by a crash before the server
/// starts serving. A staging dir without a durable `COMMITTED` marker is a
/// transaction that never crossed the commit point: discard it. One with the
/// marker is a committed transaction: install every staged file it contains,
/// idempotently, then discard it.
async fn recover_all_datasets(data_dir: &Path) -> std::io::Result<()> {
    let mut root = match tokio::fs::read_dir(data_dir).await {
        Ok(rd) => rd,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(()),
        Err(e) => return Err(e),
    };
    loop {
        let entry = match root.next_entry().await? {
            Some(e) => e,
            None => break,
        };
        if !entry.file_type().await?.is_dir() {
            continue;
        }
        let ds_dir = entry.path();
        let mut rd = match tokio::fs::read_dir(&ds_dir).await {
            Ok(rd) => rd,
            Err(_) => continue,
        };
        loop {
            let child = match rd.next_entry().await? {
                Some(c) => c,
                None => break,
            };
            let name = child.file_name();
            let name = name.to_string_lossy();
            let Some(rest) = name.strip_prefix(".txn-") else {
                continue;
            };
            if rest.is_empty() {
                continue;
            }
            let staging = child.path();
            let committed = staging.join("COMMITTED");
            if tokio::fs::metadata(&committed).await.is_ok() {
                redo_committed(&ds_dir, &staging).await?;
            } else {
                let _ = tokio::fs::remove_dir_all(&staging).await;
            }
        }
    }
    Ok(())
}

/// Finish a committed transaction found during recovery by renaming every
/// staged file into the dataset directory. Renames over existing files are
/// the intended redo; they are atomic and idempotent.
async fn redo_committed(ds_dir: &Path, staging: &Path) -> std::io::Result<()> {
    let new_dir = staging.join("new");
    let mut entries = match tokio::fs::read_dir(&new_dir).await {
        Ok(rd) => rd,
        Err(_) => return Ok(()),
    };
    loop {
        let entry = match entries.next_entry().await? {
            Some(e) => e,
            None => break,
        };
        let target = ds_dir.join(entry.file_name());
        tokio::fs::rename(entry.path(), &target).await?;
    }
    fsync_dir(ds_dir).await?;
    let _ = tokio::fs::remove_dir_all(staging).await;
    Ok(())
}

