    // durable, then persist the commit marker: this is the single commit
    // point.
    if let Err(e) = fsync_dir(&staged_dir).await {
        tracing_error(&e);
        cleanup.rm_rf().await;
        return Err(internal());
    }
    if let Err(e) = fsync_dir(&backup_dir).await {
        tracing_error(&e);
        cleanup.rm_rf().await;
        return Err(internal());
    }
