/// Write a file via a freshly created handle and fsync its contents.
async fn write_fsynced(path: &StdPath, body: &[u8]) -> std::io::Result<()> {
    let mut file = tokio::fs::File::create(path).await?;
    tokio::io::AsyncWriteExt::write_all(&mut file, body).await?;
    file.sync_all().await?;
    Ok(())
}

/// fsync a directory so that file creations and renames inside it survive a
/// crash or power loss.
async fn fsync_dir(path: &StdPath) -> std::io::Result<()> {
    let file = tokio::fs::File::open(path).await?;
    file.sync_all().await
}

async fn set_mtime(path: &StdPath, when: SystemTime) -> std::io::Result<()> {
    // std::fs::File::set_modified is a single utimensat() in practice; the
    // blocking call is negligible while the batch lock is held.
    let path = path.to_owned();
    tokio::task::spawn_blocking(move || std::fs::File::open(&path)?.set_modified(when))
        .await
        .expect("set_mtime task")
}

