189	/// Write the record atomically: temp file + fsync + rename + dir fsync, so a
190	/// crash either leaves the old value intact or the new one fully in place.
191	async fn persist_record(
192	    state: &AppState,
193	    name: &str,
194	    key: &str,
195	    body: &[u8],
196	) -> Result<(), Response> {
197	    let dir = state.data_dir.join(name);
198	    if let Err(e) = tokio::fs::create_dir_all(&dir).await {
199	        tracing_error(&e);
200	        return Err(error_response(
201	            StatusCode::INTERNAL_SERVER_ERROR,
202	            "internal",
203	        ));
204	    }
205	
206	    static TMP_COUNTER: AtomicU64 = AtomicU64::new(0);
207	    let tmp = dir.join(format!(
208	        ".tmp-{}-{}",
209	        std::process::id(),
210	        TMP_COUNTER.fetch_add(1, Ordering::Relaxed)
211	    ));
212	
213	    let result = async {
214	        let mut file = tokio::fs::File::create(&tmp).await?;
215	        tokio::io::AsyncWriteExt::write_all(&mut file, body).await?;
216	        file.sync_all().await?;
217	        tokio::fs::rename(&tmp, record_path(state, name, key)).await?;
218	        // Fsync the directory so the rename itself is durable.
219	        let dir_file = tokio::fs::File::open(&dir).await?;
220	        dir_file.sync_all().await?;
