/// idempotently, then discard it.
async fn recover_all_datasets(data_dir: &StdPath) -> std::io::Result<()> {
    let mut root = match tokio::fs::read_dir(data_dir).await {
        Ok(rd) => rd,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(()),
        Err(e) => return Err(e),
