/// Restore records already replaced by a failed commit to their pre-batch
/// bytes and mtime. Records that did not pre-exist are removed.
async fn rollback_batch(
    state: &AppState,
    name: &str,
    installed: &[StagedRecord],
    backup_dir: &StdPath,
) {
    for rec in installed {
        let target = record_path(state, name, rec.key.as_str());
        match &rec.old {
            Some((bytes, mtime)) => {
                let tmp = backup_dir.join(format!(".restore-{}.json", rec.key));
                // Stamp the old mtime on the staged inode so the rename
                // restores the pre-batch timestamp exactly.
                if stage_file(&tmp, bytes, Some(*mtime)).await.is_ok() {
                    if tokio::fs::rename(&tmp, &target).await.is_err() {
                        let _ = tokio::fs::remove_file(&tmp).await;
                    }
                }
            }
            None => {
                let _ = tokio::fs::remove_file(&target).await;
            }
        }
    }
    let dir = state.data_dir.join(name);
    let _ = fsync_dir(&dir).await;
}

