123	/// PUT /datasets/{name}/records — write a whole batch atomically: either
124	/// every record lands or the dataset is left byte-for-byte as it was.
125	async fn put_records_batch(
126	    State(state): State<AppState>,
127	    Path(name): Path<String>,
128	    body: Bytes,
129	) -> Response {
130	    if !valid_identifier(&name) {
131	        return error_response(StatusCode::BAD_REQUEST, "invalid_identifier");
132	    }
133	    if body.is_empty() {
134	        return error_response(StatusCode::BAD_REQUEST, "invalid_json");
135	    }
136	    // Missing/non-array `records`, non-object entries, a missing/wrong-typed
137	    // `key` or a missing `value` all fail to deserialize.
138	    let parsed: BatchRequestBody = match serde_json::from_slice(&body) {
139	        Ok(parsed) => parsed,
140	        Err(_) => return error_response(StatusCode::BAD_REQUEST, "invalid_json"),
141	    };
142	
143	    // Identifier rule applies to every key in the batch.
144	    for record in &parsed.records {
145	        if !valid_identifier(&record.key) {
146	            return error_response(StatusCode::BAD_REQUEST, "invalid_identifier");
147	        }
148	    }
149	    // A key may appear at most once per batch.
150	    let mut seen = HashSet::new();
151	    for record in &parsed.records {
152	        if !seen.insert(record.key.as_str()) {
153	            return error_response(StatusCode::BAD_REQUEST, "invalid_json");
154	        }
155	    }
156	
157	    let mut entries: Vec<(String, Value)> = parsed
158	        .records
159	        .into_iter()
160	        .map(|r| (r.key, r.value))
161	        .collect();
162	
163	    let lock = state.dataset_lock(&name).await;
164	    let _guard = lock.write().await;
165	
166	    // Finish any transaction interrupted in a previous process.
167	    if let Err(e) = recover_dataset(&state.data_dir.join(&name)).await {
168	        tracing_error(&e);
169	        return error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal");
170	    }
171	
172	    // An empty batch is valid and changes nothing, not even the dataset
173	    // directory's existence.
174	    if entries.is_empty() {
175	        return Json(json!({ "name": name, "records": [] })).into_response();
176	    }
177	
178	    let applied = match persist_batch(&state, &name, &entries).await {
179	        Ok(applied) => applied,
180	        Err(resp) => return resp,
181	    };
182	    let timestamps: HashMap<String, SystemTime> = applied.into_iter().collect();
183	
184	    // Byte-wise order on UTF-8 is Unicode code-point order.
185	    entries.sort_by(|a, b| a.0.cmp(&b.0));
186	    let records: Vec<Value> = entries
187	        .into_iter()
188	        .map(|(key, value)| {
189	            json!({
190	                "key": key,
191	                "value": value,
192	                "updatedAt": format_rfc3339_utc(timestamps[&key]),
193	            })
194	        })
195	        .collect();
196	    Json(json!({ "name": name, "records": records })).into_response()
197	}
