199	/// Write the record atomically: temp file + fsync + rename + dir fsync, so a
200	/// crash either leaves the old value intact or the new one fully in place.
201	async fn persist_record(
202	    state: &AppState,
203	    name: &str,
204	    key: &str,
205	    body: &[u8],
206	) -> Result<(), Response> {
207	    let dir = state.data_dir.join(name);
208	    if let Err(e) = tokio::fs::create_dir_all(&dir).await {
209	        tracing_error(&e);
210	        return Err(error_response(
211	            StatusCode::INTERNAL_SERVER_ERROR,
212	            "internal",
213	        ));
214	    }
215	
216	    static TMP_COUNTER: AtomicU64 = AtomicU64::new(0);
217	    let tmp = dir.join(format!(
218	        ".tmp-{}-{}",
219	        std::process::id(),
220	        TMP_COUNTER.fetch_add(1, Ordering::Relaxed)
221	    ));
222	
223	    let result = async {
224	        let mut file = tokio::fs::File::create(&tmp).await?;
225	        tokio::io::AsyncWriteExt::write_all(&mut file, body).await?;
226	        file.sync_all().await?;
227	        tokio::fs::rename(&tmp, record_path(state, name, key)).await?;
228	        // Fsync the directory so the rename itself is durable.
229	        let dir_file = tokio::fs::File::open(&dir).await?;
230	        dir_file.sync_all().await?;
231	        Ok::<(), std::io::Error>(())
232	    }
233	    .await;
234	
235	    if let Err(e) = result {
236	        let _ = tokio::fs::remove_file(&tmp).await;
237	        tracing_error(&e);
238	        return Err(error_response(
239	            StatusCode::INTERNAL_SERVER_ERROR,
240	            "internal",
241	        ));
242	    }
243	    Ok(())
244	}
