250	/// One staged record ready to be installed: key, its completion timestamp
251	/// and the record's prior on-disk mtime, if it already existed.
252	struct StagedRecord {
253	    key: String,
254	    when: SystemTime,
255	    old_mtime: Option<SystemTime>,
256	}
257	
258	/// Manifest entry persisted before the commit marker, naming every key in
259	/// the batch and its pre-batch mtime (null for keys that did not exist).
260	fn manifest_json(staged: &[StagedRecord]) -> Value {
261	    let keys: Vec<Value> = staged
262	        .iter()
263	        .map(|r| {
264	            json!({
265	                "key": r.key,
266	                "old": r.old_mtime.map(systemtime_nanos),
267	            })
268	        })
269	        .collect();
270	    json!({ "keys": keys })
271	}
